INSERT INTO blog_posts (id, slug, status, region_id, title, title_highlight, summary, lede, destination, cta_title, cover_url, cover_url_small, cover_alt, featured, body, reading_minutes)
VALUES ('8c2f4e6a-1b7d-4a53-9e08-3d5a7c1f9b42', 'buenos-aires-em-3-dias', 'draft', 'america-do-sul', 'Buenos Aires em 3 dias: uma região por dia, na ordem certa', 'na ordem certa', 'Roteiro de Buenos Aires em 3 dias dividido em três regiões, na ordem sábado, domingo e segunda, com horários oficiais conferidos em 14/10/2026 e o guia em PDF para baixar de graça.', 'Sábado no centro, domingo em San Telmo e La Boca, segunda em Recoleta e Palermo, com horários conferidos em outubro de 2026 e o guia completo para levar no celular.', 'Buenos Aires', NULL, '/assets/blog/buenos-aires-3-dias.jpg', '/assets/blog/buenos-aires-3-dias-m.jpg', 'Casas de chapa pintadas de azul, vermelho, amarelo e verde no Caminito, em La Boca, sob céu azul', 0, '[{"t":"pdf","href":"/guias/buenos-aires-em-3-dias.pdf","note":"PDF de 14 páginas, feito para ler no celular. Grátis, sem cadastro."},{"t":"p","text":"Deixe San Telmo para o domingo: é quando a feira acontece. Este roteiro divide Buenos Aires em **três regiões, uma por dia**, e a ordem ideal é **sábado, domingo e segunda**: no sábado há visita guiada na Casa Rosada e no domingo, a feira de San Telmo."},{"t":"tip","items":["**Escolha datas** com um sábado e um domingo seguidos.","**Reserve a visita da Casa Rosada** até 15 dias antes.","**Confira os horários na véspera**, nos sites oficiais listados no fim da página."],"title":"Como usar este roteiro"},{"t":"whatsapp"},{"t":"afiliado"},{"t":"h","text":"Centro","label":"Dia 1 · sábado"},{"t":"p","text":"Plaza de Mayo, Casa Rosada e Puerto Madero, a pé."},{"t":"img","src":"/assets/blog/buenos-aires-casa-rosada.jpg","alt":"Fachada rosa da Casa Rosada, com cúpula de zinco e a bandeira argentina, sob céu azul","caption":"A Casa Rosada, na Plaza de Mayo.","credit":"Foto: Leonardo Delsabio / Pexels","w":867,"h":867},{"t":"ul","items":["**Manhã, Plaza de Mayo e Casa Rosada:** a visita guiada é gratuita, aos sábados, das 10h às 18h, com reserva feita até 15 dias antes. Quando não há vagas, o site avisa.","**Depois, Museo Casa Rosada:** fica atrás da Casa Rosada, na antiga Aduana Taylor. Abre de quarta a domingo, das 11h às 18h (última entrada 17h30), com entrada gratuita e sem reserva.","**Fim do dia, Puerto Madero:** antigo porto com o Puente de la Mujer e restaurantes à beira do canal. Bom para o pôr do sol.","**Opcional, Avenida de Mayo:** seus cafés antigos."]},{"t":"img","src":"/assets/blog/buenos-aires-puerto-madero.jpg","alt":"Puente de la Mujer, ponte branca de mastro inclinado, sobre a água de Puerto Madero ao entardecer","caption":"O Puente de la Mujer, em Puerto Madero.","credit":"Foto: Andre Moura / Pexels","w":954,"h":715},{"t":"tip","items":["**Como chegar:** metrô (subte) até as estações Plaza de Mayo, Catedral ou Bolívar.","**Reserve antes:** a visita guiada da Casa Rosada em visitas.casarosada.gob.ar.","**Estimativa da Rota Certa, não é dado oficial:** cerca de 4 a 5 horas nas atrações e uns 30 minutos a pé entre as paradas (cerca de 2 km). Esforço baixo: tudo plano."],"title":"Para planejar o Dia 1"},{"t":"passeio","busca":"Buenos Aires centro Casa Rosada","title":"Passeios pelo centro de Buenos Aires"},{"t":"h","text":"San Telmo e La Boca","label":"Dia 2 · domingo"},{"t":"p","text":"De manhã, a feira de San Telmo. À tarde, as casas coloridas do Caminito."},{"t":"img","src":"/assets/blog/buenos-aires-san-telmo.jpg","alt":"Rua de San Telmo entre prédios antigos, com barracas brancas e uma multidão na feira de domingo","caption":"A feira de San Telmo, num domingo.","credit":"Foto: Beatriz Neves / Pexels","w":760,"h":760},{"t":"p","text":"**A feira é só aos domingos.** Os sites da Prefeitura informam das 10h às 17h ou das 11h às 17h. Chegue de manhã, quando as barracas já estão montadas."},{"t":"ul","items":["**Manhã, feira de San Telmo e Plaza Dorrego:** antiguidades e artesanato na Plaza Dorrego e nas ruas em volta. Todo domingo, a praça também recebe o Patio de Tango.","**Tarde, Caminito, em La Boca:** rua de casas coloridas, aberta todos os dias e sem ingresso. Do centro até lá, uns 30 minutos de táxi, segundo a Prefeitura de Buenos Aires.","**Opcional, perto do Caminito, Museo Quinquela Martín e Colón Fábrica:** o Museo Quinquela abre de terça a domingo, das 11h15 às 18h, com ingresso. A Colón Fábrica, oficina do Teatro Colón, abre todos os dias, das 10h às 18h."]},{"t":"tip","items":["**Entre os bairros:** táxi ou ônibus.","**Dica da Rota Certa:** em La Boca, fique na área do Caminito e volte antes de escurecer.","**Estimativa da Rota Certa, não é dado oficial:** cerca de 5 horas nas atrações. Esforço moderado: calçamento de pedra."],"title":"Para planejar o Dia 2"},{"t":"passeio","busca":"San Telmo La Boca Buenos Aires","title":"Passeios em San Telmo e La Boca"},{"t":"h","text":"Recoleta e Palermo","label":"Dia 3 · segunda"},{"t":"p","text":"Cemitério histórico, a flor de aço, museus e parques."},{"t":"img","src":"/assets/blog/buenos-aires-recoleta.jpg","alt":"Corredor estreito entre mausoléus de pedra no Cemitério da Recoleta, com uma pessoa ao fundo","caption":"Um corredor entre mausoléus no Cemitério da Recoleta.","credit":"Foto: Gabriel Ramos / Pexels","w":867,"h":867},{"t":"p","text":"**Atenção ao dia da semana:** o Rosedal de Palermo fecha às segundas e o MALBA, às terças. Numa segunda, troque o Rosedal por um passeio nos Bosques de Palermo."},{"t":"ul","items":["**Manhã, Cementerio de la Recoleta:** todos os dias, das 9h às 17h, na Rua Junín, 1760. A entrada é gratuita só para residentes na Argentina; turistas estrangeiros pagam ingresso.","**15 min a pé, Floralis Genérica:** escultura gigante de aço em forma de flor, num parque aberto. Sem ingresso.","**Opcional, MALBA, museu de arte latino-americana:** quarta, das 11h às 20h; quinta a segunda, das 12h às 20h. Fecha às terças. Com ingresso.","**Tarde, Bosques de Palermo e Rosedal:** parque com lagos. O Rosedal é grátis e abre de terça a domingo. À noite, jante em Palermo."]},{"t":"img","src":"/assets/blog/buenos-aires-floralis.jpg","alt":"Escultura Floralis Genérica, uma grande flor de aço polido com as pétalas abertas, num parque","caption":"A Floralis Genérica, a flor de aço de Palermo.","credit":"Foto: Sabrina Ibarra / Pexels","w":867,"h":867},{"t":"tip","items":["**Estimativa da Rota Certa, não é dado oficial:** cerca de 4 a 5 horas nas atrações e uns 45 minutos a pé entre as paradas (cerca de 3,5 km). Esforço moderado: dia de caminhada."],"title":"Para planejar o Dia 3"},{"t":"passeio","busca":"Recoleta Palermo Buenos Aires","title":"Passeios em Recoleta e Palermo"},{"t":"h","text":"Como chegar e se locomover","label":"Na prática"},{"t":"p","text":"Buenos Aires tem dois aeroportos: Ezeiza (EZE) e Aeroparque (AEP), mais perto do centro."},{"t":"ul","items":["**Do aeroporto de Ezeiza:** táxi oficial, remís (carro com motorista, pago antes), ônibus de empresas como a Tienda León até Puerto Madero e a linha 8 de ônibus, que costuma lotar e tem pouco espaço para mala. O trajeto leva cerca de 50 minutos.","**Metrô (subte) e ônibus:** cartões Visa e Mastercard por aproximação funcionam nas catracas \"multipago\", inclusive cartões emitidos no Brasil. Também vale o cartão SUBE, vendido na cidade.","**Use sempre o mesmo cartão:** a tarifa com desconto progressivo só vale quando você paga sempre com o mesmo cartão e a mesma forma de pagamento.","**Tomada e voltagem:** a Argentina usa 220 V e tomada de três pinos chatos (padrão IRAM 2073). Leve um adaptador."]},{"t":"h","text":"Documentos, seguro e checklist","label":"Antes de ir"},{"t":"p","text":"**Brasileiro entra só com o RG.** Pelo acordo do Mercosul, vale a carteira de identidade emitida pelos estados (RG) ou o passaporte válido. Leve o documento original e legível; a companhia aérea pode ter regras próprias."},{"t":"p","text":"**Seguro-saúde:** a lei de migração argentina, alterada em 2025, prevê que o viajante declare ter seguro-saúde, e os hospitais públicos nacionais passaram a cobrar de quem não mora no país. Viaje com seguro."},{"t":"ul","items":["RG original e legível, ou passaporte válido.","Seguro-saúde de viagem.","Visita da Casa Rosada reservada para o sábado.","O domingo livre para a feira de San Telmo.","Cartão Visa ou Mastercard por aproximação, um por pessoa.","Adaptador de tomada.","Horários conferidos na véspera."]},{"t":"p","text":"**Orçamento:** o preço da passagem não é o preço da viagem. O guia em PDF tem a tabela pronta. O câmbio muda rápido na Argentina: os preços em pesos estão nos sites oficiais, e vale converter para reais na data da compra."},{"t":"pdf","href":"/guias/buenos-aires-em-3-dias.pdf","note":"Leve o roteiro, as rotas a pé no Google Maps e o orçamento no celular. Grátis, sem cadastro."},{"t":"tip","items":["Casa Rosada: [visitas guiadas](https://visitas.casarosada.gob.ar/) e [Museo Casa Rosada](https://www.argentina.gob.ar/secretariageneral/museo-casa-rosada/horarios-e-informacion)","San Telmo: [feira](https://buenosaires.gob.ar/museos/buenos-aires-museo/ferias-permanentes-y-temporarias) e [Patio de Tango](https://turismo.buenosaires.gob.ar/es/atractivo/feria-de-san-telmo)","La Boca: [turismo de Buenos Aires](https://turismo.buenosaires.gob.ar/es/circuitos-buenos-aires-sur/la-boca-cultural)","[Cementerio de la Recoleta: Prefeitura de Buenos Aires](https://buenosaires.gob.ar/gobierno/gestion-comunal/cementerios-de-la-ciudad/cementerio-de-la-recoleta)","[MALBA](https://malba.org.ar/en/visitar/)","[Rosedal de Palermo](https://turismo.buenosaires.gob.ar/en/article/el-rosedal)","[Subte com cartão: Prefeitura de Buenos Aires](https://buenosaires.gob.ar/noticias/se-habilito-el-pago-del-subte-con-celulares-tarjetas-de-debito-y-credito)","[Aeroporto de Ezeiza: Aeropuertos Argentina](http://www.aa2000.com.ar/ezeiza/Transporte)","[Documentos: Migraciones](https://www.argentina.gob.ar/migraciones/documentos-de-viaje-del-mercosur)","Seguro-saúde: [Lei 25.871](https://www.argentina.gob.ar/normativa/nacional/ley-25871-92016/actualizacion) e [Ministério da Saúde](https://www.argentina.gob.ar/noticias/los-hospitales-nacionales-comenzaran-cobrarles-los-extranjeros-no-residentes-en-el-pais)","[Tomada: Resolução 524/1998](https://www.argentina.gob.ar/normativa/recurso/52535/texact/htm)"],"title":"Fontes oficiais, conferidas em 14/10/2026"},{"t":"p","text":"Horários, preços e regras mudam: confira nos sites acima antes de ir. O guia não fixa preços em pesos argentinos; os valores estão nos sites oficiais."},{"t":"p","text":"Foto de capa: Miguel Cuenca / Pexels."},{"t":"whatsapp"},{"t":"contato"},{"t":"afiliado"}]', 5);
